```csharp
using System;
using System.Security.Cryptography;
public static string genSignature(string nonce, long timestamp, string
accessKeySecret)
var encoding = new System.Text.UTF8Encoding();
byte[] keyBytes = encoding.GetBytes(accessKeySecret);
string msg = nonce+"&"+Convert.ToString(timestamp);
byte[] msgBytes = encoding.GetBytes(msg);
using(var hmacsha256 = new HMACSHA256(keyBytes))
byte[] hashmsg = hmacsha256.ComputeHash(msgBytes);
return Convert.ToBase64String(hashmsg);
