```javascript
const crypto = require('crypto');
function genSignature(nonce, timestamp, access_key_secret) {
const message = `${nonce}&${timestamp}`;
const hmac = crypto.createHmac('sha256', access_key_secret);
hmac.update(message);
const digest = hmac.digest('hex');
const signature = Buffer.from(digest, 'hex').toString('base64');
return signature;
